use aap::caps::kb_read;
use aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM: &str = "You are a customer-support assistant. Answer the question using the provided knowledge. If you need more information, request the `lookup` tool.";
const MAX_QUESTION_CHARS: usize = 512;
const MAX_ROUNDS: usize = 4;

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn intent_name(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(ctx: &ConversationContext, lookups: &[String]) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_name(ctx.intent));
    p.push('\n');
    p.push_str("Question: ");
    p.push_str(&ctx.question);
    p.push('\n');
    p.push_str("Knowledge:\n");
    for k in &ctx.knowledge {
        p.push_str("- ");
        p.push_str(k);
        p.push('\n');
    }
    for l in lookups {
        p.push_str("Tool result: ");
        p.push_str(l);
        p.push('\n');
    }
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return fail("question exceeds 512 characters");
        }

        let mut lookups: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx, &lookups);
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return fail("model requested a tool outside the granted scope");
                    }
                    let hits = kb_read::lookup(&req.query);
                    lookups.push(format!("lookup({}) -> {}", req.query, hits.join(" | ")));
                }
            }
        }

        fail("tool-orchestration round limit reached")
    }
}

export!(Node);
```

